"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["74725"],{42418(e){e.exports=JSON.parse('{"id":"FIN-1400","slug":"expected-shortfall","term":"Expected Shortfall","also_known_as":[],"difficulty":"Advanced","definition":"Expected shortfall is a measure of risk that estimates the average loss a portfolio would suffer in the worst cases beyond a given confidence level, such as the worst 2.5% or 5% of outcomes.","explanation":["Value at Risk tells you the loss that will not be exceeded at a certain confidence level, but says nothing about how bad losses could be beyond that point. Expected shortfall, also called conditional value at risk, fills this gap by averaging the losses in the tail.","For example, a portfolio\'s one-day 95% Value at Risk might be 2,000,000, meaning losses exceed that amount on about 5% of days. Its expected shortfall at 95% might be 3,100,000, the average loss on those worst days.","Expected shortfall gives a better picture of tail risk, particularly for portfolios that can suffer rare but very large losses. It also has mathematical properties that make it more consistent when risks from different portfolios are combined.","After the 2008 financial crisis, banking regulators moved towards expected shortfall for measuring market risk, replacing Value at Risk in the main capital framework for banks\' trading activities. Like any model, its accuracy depends on the data and assumptions used, especially about rare events."],"note":"","total":1500,"prev":{"slug":"expected-return","term":"Expected Return"},"next":{"slug":"expected-value","term":"Expected Value"}}')}}]);